// RF-01 y RNF-05: toda solicitud entra por aquí, venga del webhook o del ejemplo,
// y queda registrada con su canal, fecha y hora.
const s = $json.body ?? $json;
const canal = s.canal || 'WhatsApp';
return {
  json: {
    idSolicitud: 'SOL-' + Date.now(),
    canalOrigen: canal,
    mensajeOriginal: String(s.mensaje || ''),
    fechaRecepcion: new Date().toISOString(),
    paciente: { telefono: String(s.telefono || ''), correo: String(s.correo || '') },
    estado: 'Recibida',
    historial: [{ fecha: new Date().toISOString(), paso: 'Solicitud recibida por ' + canal, actor: 'n8n' }],
  },
};

// RF-02: junta lo que extrajo Gemini con la solicitud registrada.
const sol = $('Registrar solicitud').first().json;
const ia = $json.output ?? {};
const limpiar = (t) => String(t ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
return {
  json: {
    ...sol,
    paciente: {
      ...sol.paciente,
      nombreCompleto: ia.nombreCompleto || '',
      tipoDocumento: ia.tipoDocumento || 'CC',
      numeroDocumento: String(ia.numeroDocumento || '').replace(/\D/g, ''),
      eps: ia.eps || '',
    },
    especialidad: limpiar(ia.especialidad) || 'medicina general',
    urgencia: limpiar(ia.urgencia) === 'alta' ? 'alta' : 'normal',
    estado: 'Datos extraídos',
    historial: [...sol.historial, { fecha: new Date().toISOString(), paso: 'Datos extraídos del mensaje', actor: 'IA (Gemini)' }],
  },
};

// RPA con datos de ejemplo. En producción, este paso lo hace el bot por pantalla en el portal o la agenda.
// RF-03: simula al bot entrando por pantalla al portal de la EPS.
const pacientesEPS = {
  '1037654321': { nombreCompleto: 'Ana Gómez', eps: 'Sura', activo: true, autorizaciones: ['dermatologia'] },
  '43210987': { nombreCompleto: 'Luisa Pérez', eps: 'Sanitas', activo: true, autorizaciones: [] },
  '98765432': { nombreCompleto: 'Carlos Ruiz', eps: 'Nueva EPS', activo: true, autorizaciones: ['cardiologia'] },
  '11223344': { nombreCompleto: 'Pedro Díaz', eps: 'Sura', activo: false, autorizaciones: [] },
};
const requiereAutorizacion = ['dermatologia', 'cardiologia'];

const s = $json;
const p = pacientesEPS[s.paciente.numeroDocumento];
const necesita = requiereAutorizacion.includes(s.especialidad);
const activo = Boolean(p && p.activo);
const autorizado = activo && (!necesita || p.autorizaciones.includes(s.especialidad));
let motivo = '';
if (!p) motivo = 'El documento no aparece en el portal de la EPS';
else if (!activo) motivo = 'El paciente está inactivo en la EPS';
else if (!autorizado) motivo = 'La especialidad requiere autorización y el paciente no la tiene';

return {
  json: {
    ...s,
    paciente: {
      ...s.paciente,
      nombreCompleto: s.paciente.nombreCompleto || (p ? p.nombreCompleto : ''),
      eps: p ? p.eps : s.paciente.eps,
      afiliacionActiva: activo,
    },
    autorizacionVigente: autorizado,
    codigoAutorizacion: autorizado && necesita ? 'AUT-' + s.paciente.numeroDocumento : '',
    motivoExcepcion: motivo,
    estado: motivo ? 'No agendable' : 'Verificada en EPS',
    historial: [...s.historial, { fecha: new Date().toISOString(), paso: motivo || 'Paciente activo y autorizado en el portal EPS', actor: 'Bot RPA' }],
  },
};

// RPA con datos de ejemplo. En producción, este paso lo hace el bot por pantalla en el portal o la agenda.
// RF-04: simula al bot buscando el cupo más cercano en la agenda de la IPS.
// El primer cupo de cada especialidad queda para las solicitudes urgentes.
const agenda = {
  'medicina general': { medico: 'Dra. Laura Mejía', consultorio: 'Consultorio 101', horas: [7, 8, 9, 14, 15] },
  'odontologia': { medico: 'Dr. Felipe Mora', consultorio: 'Consultorio 204', horas: [8, 11] },
  'pediatria': { medico: 'Dra. Sara Ríos', consultorio: 'Consultorio 110', horas: [9, 16] },
  'dermatologia': { medico: 'Dr. Juan Ochoa', consultorio: 'Consultorio 302', horas: [10] },
  'cardiologia': { medico: 'Dr. Andrés Gil', consultorio: 'Consultorio 305', horas: [] },
};

const s = $json;
const m = agenda[s.especialidad] ?? agenda['medicina general'];

// Cupos de los próximos 5 días hábiles
const cupos = [];
const dia = new Date();
let habiles = 0;
while (habiles < 5) {
  dia.setDate(dia.getDate() + 1);
  if (dia.getDay() === 0 || dia.getDay() === 6) continue;
  habiles++;
  const fecha = dia.toISOString().slice(0, 10);
  for (const h of m.horas) cupos.push(fecha + 'T' + String(h).padStart(2, '0') + ':00:00-05:00');
}

const desde = s.citaAnterior ? s.citaAnterior.fechaHora : '';
let libres = cupos.filter((c) => c > desde);
if (s.urgencia !== 'alta') libres = libres.slice(1);
const elegido = libres[0];

return {
  json: {
    ...s,
    hayEspacio: Boolean(elegido),
    cita: elegido
      ? { fechaHora: elegido, especialidad: s.especialidad, medicoAsignado: m.medico, consultorio: m.consultorio }
      : (s.cita ?? null),
    motivoExcepcion: elegido ? '' : 'No hay espacio en ' + s.especialidad + ' en los próximos 5 días hábiles',
    estado: elegido ? 'Espacio encontrado' : 'Sin espacio',
    historial: [...s.historial, { fecha: new Date().toISOString(), paso: elegido ? 'Espacio encontrado: ' + elegido : 'Sin espacio en la agenda', actor: 'Bot RPA' }],
  },
};

// RPA con datos de ejemplo. En producción, este paso lo hace el bot por pantalla en el portal o la agenda.
// RF-05: simula al bot registrando la cita. Antes de guardar verifica que el cupo siga libre
// y que el paciente no tenga ya esa cita. Si es una reprogramación, libera el cupo anterior.
const s = $json;
const { citaAnterior, hayEspacio, ...resto } = s;
const cita = {
  ...s.cita,
  idCita: 'CITA-' + s.paciente.numeroDocumento + '-' + s.cita.fechaHora.slice(0, 16).replace(/\D/g, ''),
  estado: 'Agendada',
  confirmacionEnviada: false,
  recordatorioEnviado: false,
};
const texto = citaAnterior
  ? 'Cita movida del ' + citaAnterior.fechaHora + ' al ' + cita.fechaHora + '; cupo anterior liberado'
  : 'Cita registrada en el sistema de agendamiento';

return {
  json: {
    ...resto,
    cita,
    estado: 'Agendada',
    historial: [...s.historial, { fecha: new Date().toISOString(), paso: texto, actor: 'Bot RPA' }],
  },
};

// RF-06: confirmación por el mismo canal (simulada; en producción va el nodo de WhatsApp o Gmail).
const c = $json.cita;
const cuando = new Date(c.fechaHora).toLocaleString('es-CO', { timeZone: 'America/Bogota', dateStyle: 'full', timeStyle: 'short' });
const ips = $('Configuración').first().json.nombre_ips;
return {
  json: {
    ...$json,
    cita: { ...c, confirmacionEnviada: true },
    mensajeEnviado: {
      canal: $json.canalOrigen,
      para: $json.paciente.telefono || $json.paciente.correo,
      texto: `Hola ${$json.paciente.nombreCompleto}, tu cita de ${$json.especialidad} quedó para el ${cuando} con ${c.medicoAsignado}, ${c.consultorio}, ${ips}. Código: ${c.idCita}.`,
    },
    historial: [...$json.historial, { fecha: new Date().toISOString(), paso: 'Confirmación enviada por ' + $json.canalOrigen, actor: 'n8n' }],
  },
};

// RF-07: recordatorio 24 h antes, con opción de confirmar, cancelar o reprogramar (envío simulado).
// En la demo, abre uno de los links para responder como el paciente.
const c = $json.cita;
const cuando = new Date(c.fechaHora).toLocaleString('es-CO', { timeZone: 'America/Bogota', dateStyle: 'full', timeStyle: 'short' });
const url = $execution.resumeUrl;
const sep = url.includes('?') ? '&' : '?'; // n8n 2.x ya trae ?signature=... en el link
return {
  json: {
    ...$json,
    cita: { ...c, recordatorioEnviado: true },
    mensajeEnviado: {
      canal: $json.canalOrigen,
      para: $json.paciente.telefono || $json.paciente.correo,
      texto: `Te recordamos tu cita de ${$json.especialidad} el ${cuando} con ${c.medicoAsignado}. Responde CONFIRMO, CANCELO o REPROGRAMO.`,
    },
    responderDemo: {
      confirma: url + sep + 'respuesta=confirma',
      cancela: url + sep + 'respuesta=cancela',
      reprograma: url + sep + 'respuesta=reprograma',
    },
    historial: [...$json.historial, { fecha: new Date().toISOString(), paso: 'Recordatorio enviado', actor: 'n8n' }],
  },
};

// RF-08: toma la respuesta del paciente. Si no respondió a tiempo, queda "sin respuesta".
const sol = $('Enviar recordatorio').first().json;
const respuesta = String($json.query?.respuesta ?? '').toLowerCase().trim() || 'sin respuesta';
const { responderDemo, ...resto } = sol;
return {
  json: {
    ...resto,
    respuesta,
    historial: [...sol.historial, { fecha: new Date().toISOString(), paso: 'El paciente responde: ' + respuesta, actor: 'Paciente' }],
  },
};

// RF-08: si confirma (o no responde) la cita sigue en pie.
const estado = $json.respuesta === 'confirma' ? 'Confirmada' : 'Agendada sin respuesta';
return {
  json: {
    ...$json,
    estado,
    cita: { ...$json.cita, estado },
    historial: [...$json.historial, { fecha: new Date().toISOString(), paso: 'Cita ' + estado.toLowerCase(), actor: 'n8n' }],
  },
};

// RPA con datos de ejemplo. En producción, este paso lo hace el bot por pantalla en el portal o la agenda.
// RF-08: simula al bot cancelando la cita y liberando el cupo en la agenda.
const s = $json;
return {
  json: {
    ...s,
    cita: { ...s.cita, estado: 'Cancelada' },
    estado: 'Cancelada',
    historial: [...s.historial, { fecha: new Date().toISOString(), paso: 'Cita cancelada y cupo liberado en la agenda', actor: 'Bot RPA' }],
  },
};

// RF-08: guarda la cita actual para liberarla y vuelve a buscar espacio (RF-04).
return {
  json: {
    ...$json,
    citaAnterior: $json.cita,
    estado: 'Reprogramando',
    historial: [...$json.historial, { fecha: new Date().toISOString(), paso: 'El paciente pide otra fecha', actor: 'n8n' }],
  },
};

// RF-09 y RNF-02: el auxiliar recibe el caso con los datos ya extraídos y el motivo.
// Si la IA o el bot fallan después de 3 intentos, la solicitud también llega aquí y no se pierde.
let sol = $json;
if (!sol.idSolicitud) {
  try { sol = $('Unir datos extraídos').first().json; } catch (e) { sol = $('Registrar solicitud').first().json; }
}
const error = $json.error ? ($json.error.message || String($json.error)) : '';
const motivo = sol.motivoExcepcion || (error ? 'Falla técnica: ' + error : 'Revisar el caso');
return {
  json: {
    ...sol,
    estado: 'Excepción',
    motivoExcepcion: motivo,
    asignadoA: 'Auxiliar de agendamiento',
    historial: [...(sol.historial || []), { fecha: new Date().toISOString(), paso: 'Pasa al auxiliar: ' + motivo, actor: 'n8n' }],
  },
};

// RNF-05: registro final de la solicitud con su estado y quién actuó en cada paso.
// Simulado: en producción este nodo es un Postgres que guarda el registro en la BD.
return {
  json: {
    idSolicitud: $json.idSolicitud,
    estado: $json.estado,
    canal: $json.canalOrigen,
    paciente: $json.paciente,
    especialidad: $json.especialidad,
    urgencia: $json.urgencia,
    cita: $json.cita ?? null,
    motivoExcepcion: $json.motivoExcepcion || '',
    historial: $json.historial,
  },
};
